insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_10_v1'
from (values
('127.56.d.1.A',2,'A viticulture student wants to explore jobs. Which choice names real paths?','["Vineyard manager, grape grower, or winery owner", "Air traffic controller only", "Dairy farmer only", "Deep-sea diver only"]'::jsonb,0,'Viticulture careers include growing, managing and running a vineyard business.','original'),
('127.56.d.1.A',3,'Starting a small vineyard to sell grapes is an example of:','["A school requirement", "Entrepreneurship in viticulture", "A state holiday", "A lab safety rule"]'::jsonb,1,'Owning and running a grape-growing business is entrepreneurship.','original'),
('127.56.d.1.B',2,'Which shows professionalism on a vineyard crew?','["Ignoring the foreman", "Leaving work half done", "Showing up on time and finishing assigned pruning rows", "Arriving whenever convenient"]'::jsonb,2,'Reliable work habits matter in any job.','original'),
('127.56.d.1.B',3,'A worker sees a broken trellis wire. A professional response is to:','["Blame another worker", "Walk past it", "Cut more wires", "Report it and help repair it safely"]'::jsonb,3,'Spotting and solving problems keeps a vineyard running.','original'),
('127.56.d.1.C',2,'Why wear gloves and sturdy boots when working in a vineyard?','["To prevent cuts, scrapes, and foot injuries", "To speed up picking", "To look fashionable", "To keep grapes warm"]'::jsonb,0,'Wire, canes and tools can injure unprotected hands and feet.','original'),
('127.56.d.1.C',3,'A safe practice during a hot harvest day is to:','["Work without breaks", "Drink water often and rest in the shade", "Wear no sun protection", "Skip water"]'::jsonb,1,'Heat safety prevents illness.','original'),
('127.56.d.1.D',3,'Following labor laws about pay and safety is part of an employer''s:','["Hobbies", "Optional choices", "Legal responsibilities", "Marketing slogans"]'::jsonb,2,'Employers must follow laws that protect workers.','original'),
('127.56.d.1.D',4,'A vineyard worker who reports unsafe pesticide handling is acting:','["Selfishly", "Illegally", "Against company rules", "Ethically and in line with worker rights"]'::jsonb,3,'Reporting hazards protects everyone.','original'),
('127.56.d.1.E',2,'Which shows good citizenship in the grape-growing industry?','["Following water-use rules and helping neighbors during harvest", "Ignoring water limits", "Dumping chemicals on roads", "Refusing to cooperate"]'::jsonb,0,'Citizenship includes obeying local rules and helping others.','original'),
('127.56.d.1.E',3,'A responsible grower avoids pesticide drift by:','["Spraying in high wind", "Applying only when wind conditions are safe", "Spraying near homes", "Ignoring neighbors"]'::jsonb,1,'Drift can harm people, wildlife and neighboring crops.','original'),
('127.56.d.2.A',3,'A student plans to tend a small row of grapevines and track growth for a year. This is a(n):','["Lunch menu", "Exam schedule", "Supervised agricultural experience in viticulture", "Class trip"]'::jsonb,2,'An SAE is a planned, supervised, hands-on project.','original'),
('127.56.d.2.A',2,'A student''s vineyard project is reviewed by:','["Only classmates", "A stranger", "Nobody", "A teacher or adult supervisor"]'::jsonb,3,'Supervisors guide and evaluate the plan.','original'),
('127.56.d.2.B',2,'Why record pruning dates and yields on a grape project?','["To track progress and results over time", "To fill pages", "To lose information", "To impress strangers"]'::jsonb,0,'Records help evaluate and improve.','original'),
('127.56.d.2.B',3,'A record book for a grapevine SAE could include:','["Nothing", "Dates of spraying, hours worked, and costs", "Movie reviews", "Sports scores"]'::jsonb,1,'Complete records track the project.','original'),
('127.56.d.3.A',2,'Which activity builds leadership in a viticulture program?','["Staying silent", "Skipping events", "Leading a vineyard workday for classmates", "Avoiding responsibility"]'::jsonb,2,'Leading others builds skills.','original'),
('127.56.d.3.B',2,'A local program of activities for a grape-growing chapter might include:','["No meetings", "Cancelled events", "Secret plans", "A vineyard tour and a service day"]'::jsonb,3,'It lists the activities planned for the year.','original'),
('127.56.d.3.B',3,'A member who helps with the vineyard service day is:','["Taking part in the local program of activities", "Avoiding service", "Breaking rules", "Quitting"]'::jsonb,0,'Joining planned events supports the chapter.','original'),
('127.56.d.3.C',2,'A record of vineyard experience could list:','["Nothing", "Pruning, harvest help, and volunteer hours", "Only jokes", "Unrelated hobbies"]'::jsonb,1,'Documentation shows skills.','original'),
('127.56.d.3.C',3,'Keeping experience records current helps with:','["Losing opportunities", "Hiding work", "Applications for jobs and scholarships", "Skipping school"]'::jsonb,2,'Updated records support future plans.','original'),
('127.56.d.4.A',3,'Historical advances such as improved rootstocks are important because they:','["Replaced all vineyards", "Ended grape growing", "Had no effect", "Helped protect vines from pests and improve production"]'::jsonb,3,'Rootstock resistance saved many vineyards.','original'),
('127.56.d.4.A',4,'The spread of European grapevines to the Americas led to:','["New vineyard regions and new pests to manage", "Only wild grapes", "No vineyards", "Fewer people drinking"]'::jsonb,0,'Moving vines also moved diseases such as phylloxera.','original'),
('127.56.d.4.B',3,'An emerging technology in vineyards is:','["Hand counting only", "Drones and sensors that monitor vine health", "Paper maps only", "Candle-based irrigation"]'::jsonb,1,'Technology improves monitoring.','original'),
('127.56.d.4.B',4,'Remote sensing in a vineyard can help growers to:','["Ignore vines", "Delay harvest always", "Spot water stress before it is visible", "Stop pruning"]'::jsonb,2,'Imagery reveals variation across rows.','original'),
('127.56.d.4.C',3,'A current trend in viticulture is growing interest in:','["Using no water", "Ignoring climate", "Abandoning vineyards", "Sustainable and organic practices"]'::jsonb,3,'Consumers value sustainability.','original'),
('127.56.d.4.C',4,'Climate change has pushed growers to consider:','["Heat-tolerant varieties and new vineyard sites", "Growing only one variety", "Ignoring weather", "Planting in shade"]'::jsonb,0,'Growers adapt to warming trends.','original'),
('127.56.d.5.A',3,'Most grapevines for commercial vineyards are propagated by:','["Bird droppings", "Cuttings or grafting", "Pollen only", "Seeds only"]'::jsonb,1,'Asexual propagation keeps the variety true.','original'),
('127.56.d.5.A',4,'Grafting a scion onto a rootstock combines:','["Two sets of fruit", "Nothing", "Fruit characteristics with root traits", "Only leaves"]'::jsonb,2,'Grafts join desirable parts.','original'),
('127.56.d.5.B',3,'The tendrils of a grapevine are used to:','["Make pollen", "Drink water", "Make grapes", "Cling to supports"]'::jsonb,3,'Tendrils grasp trellis wires.','original'),
('127.56.d.5.B',4,'Grape clusters develop from:','["Flowers on new shoots", "Old trunk bark", "Roots", "Tendrils"]'::jsonb,0,'Fruit comes from fertilized flowers.','original'),
('127.56.d.5.C',3,'Rootstock is chosen to help a vine:','["Avoid light", "Resist soil pests and tolerate soil conditions", "Grow upside down", "Lose leaves"]'::jsonb,1,'Rootstocks supply resistance and vigor control.','original'),
('127.56.d.5.C',4,'Phylloxera is a root pest managed with:','["Heavy pruning", "Daily watering", "Resistant rootstocks", "Mulch only"]'::jsonb,2,'Resistant rootstocks protect vines.','original'),
('127.56.d.5.D',3,'The period when buds swell and shoots begin to grow in spring is called:','["Dormancy", "Harvest", "Veraison", "Budbreak"]'::jsonb,3,'Budbreak starts the growing season.','original'),
('127.56.d.5.D',4,'Veraison is when grapes:','["Begin to soften and change color", "Bloom", "Are harvested", "Fall off"]'::jsonb,0,'Color change marks ripening onset.','original'),
('127.56.d.5.E',3,'Too much rain near harvest can cause:','["Fewer pests", "Fruit splitting and rot", "Higher sugar always", "Better flavor"]'::jsonb,1,'Excess moisture promotes disease.','original'),
('127.56.d.5.E',4,'Cool nights and warm days in late season often help grapes:','["Rot", "Lose all sugar", "Develop color and acid balance", "Stop ripening"]'::jsonb,2,'Day-night temperature swings affect ripening.','original'),
('127.56.d.5.F',3,'A trellis in a vineyard is used to:','["Hold water", "Attract birds", "Shade the soil", "Support and position the vines"]'::jsonb,3,'Training systems organize canopy.','original'),
('127.56.d.5.F',4,'A benefit of training vines onto wires is:','["Better sunlight exposure and airflow", "Less light", "Weaker vines", "More humidity"]'::jsonb,0,'Canopy management reduces disease.','original'),
('127.56.d.6.A',3,'A good vineyard site generally has:','["Standing water", "Well-drained soil and adequate sunlight", "Deep shade", "Constant flooding"]'::jsonb,1,'Drainage and light are key.','original'),
('127.56.d.6.A',4,'A slope facing the sun can help a vineyard by:','["Causing flooding", "Blocking light", "Improving warmth and air drainage", "Raising frost risk only"]'::jsonb,2,'Slopes drain cold air and warm earlier.','original'),
('127.56.d.6.B',3,'Before planting, growers test the soil to learn its:','["Age", "Price", "Color name", "Texture, pH, and nutrient levels"]'::jsonb,3,'Soil tests guide site decisions.','original'),
('127.56.d.6.B',4,'A site with a late-spring frost history is risky because it can:','["Kill new shoots after budbreak", "Add sugar", "Help rooting", "Improve yields"]'::jsonb,0,'Frost damage reduces crops.','original'),
('127.56.d.6.C',3,'Studying successful vineyards in other regions helps growers to:','["Avoid planning", "Learn practices that suit similar conditions", "Ignore climate", "Copy blindly"]'::jsonb,1,'Comparing sites guides decisions.','original'),
('127.56.d.6.C',4,'Researchers compare regions with similar climates because:','["Weather is irrelevant", "Soil never matters", "Varieties that thrive there may do well locally", "All grapes grow everywhere"]'::jsonb,2,'Similar conditions favor similar varieties.','original'),
('127.56.d.6.D',3,'A vineyard design plan should include:','["Menu items", "Party details", "Staff birthdays", "Row spacing, orientation, and irrigation layout"]'::jsonb,3,'Layout affects efficiency.','original'),
('127.56.d.6.D',4,'Rows running north to south often help by:','["Giving even sunlight on both sides of the canopy", "Raising frost", "Blocking sun", "Reducing air flow"]'::jsonb,0,'Orientation balances light.','original'),
('127.56.d.7.A',3,'Cold injury to plants occurs when temperatures:','["Stay mild", "Drop low enough to damage tissue", "Rise too high", "Stay constant"]'::jsonb,1,'Freezing damages cells.','original'),
('127.56.d.7.A',4,'Winter injury risk is greatest after:','["Heavy irrigation", "Steady cold", "A sudden hard freeze following mild weather", "A cloudy day"]'::jsonb,2,'Vines lose hardiness during warm spells.','original'),
('127.56.d.7.B',3,'Blackened, shriveled shoots after a spring freeze are signs of:','["Overwatering", "Healthy growth", "Nutrient surplus", "Frost damage"]'::jsonb,3,'Frozen tissue turns dark.','original'),
('127.56.d.7.B',4,'One way to reduce frost damage is to:','["Use wind machines to mix warmer air downward", "Water less", "Prune early only", "Do nothing"]'::jsonb,0,'Mixing air raises canopy temperature.','original'),
('127.56.d.7.C',3,'A radiation frost happens on:','["Windy cloudy days", "Calm, clear nights when heat escapes to the sky", "Rainy mornings", "Hot afternoons"]'::jsonb,1,'Radiation frosts form near the ground.','original'),
('127.56.d.7.C',4,'An advection frost is caused by:','["Warm fog", "Heat waves", "A mass of cold air moving in with wind", "Still clear skies"]'::jsonb,2,'Advection frosts bring cold air in.','original'),
('127.56.d.7.D',3,'A passive frost protection technique is:','["Running fans", "Using sprinklers", "Burning heaters", "Choosing late-budding varieties or a good site"]'::jsonb,3,'Passive methods avoid frost risk without energy input.','original'),
('127.56.d.7.D',4,'Delaying pruning in spring can help because it:','["Postpones budbreak and lowers frost risk", "Kills roots", "Triggers early budbreak", "Makes vines freeze"]'::jsonb,0,'Late pruning delays bud development.','original'),
('127.56.d.7.E',3,'An active frost protection method is:','["Choosing a site", "Running wind machines or overhead sprinklers", "Waiting for spring", "Planting a new variety"]'::jsonb,1,'Active methods add heat or mix air.','original'),
('127.56.d.7.E',4,'Overhead sprinklers protect buds by:','["Adding sugar", "Cooling them", "Releasing heat as water freezes", "Washing dust"]'::jsonb,2,'Freezing water releases latent heat.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
