insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_10_v1'
from (values
('127.57.d.1.E',4,'Sustainable practices that fit good citizenship include:','["Discarding everything", "Burning plastic", "Recycling floral waste and reducing foam use", "Dumping chemicals"]'::jsonb,2,'Responsible practices protect the environment.','original'),
('127.57.d.2.A',3,'A student plans to design arrangements for weddings and track costs and sales across a year. This SAE is best called:','["A pop quiz", "A holiday break", "A school dance", "A supervised agricultural experience in advanced floral design"]'::jsonb,3,'An SAE is a planned, supervised project.','original'),
('127.57.d.2.A',2,'Who supervises an advanced floral SAE?','["A teacher or supervising adult", "Only a friend", "Only a client", "No one"]'::jsonb,0,'Supervision keeps projects on track.','original'),
('127.57.d.2.B',3,'Why record material costs, labor hours, and sales for each event design?','["To waste time", "To evaluate profitability and improve", "To hide expenses", "To fill pages"]'::jsonb,1,'Records show the real cost of work.','original'),
('127.57.d.2.B',2,'A good SAE record in floral design includes:','["Movie lists", "Doodles", "Dates, designs, and income", "Sports"]'::jsonb,2,'Complete records support evaluation.','original'),
('127.57.d.3.A',3,'A floral design student builds leadership by:','["Doing nothing", "Avoiding team roles", "Skipping events", "Organizing a prom corsage sale for the chapter"]'::jsonb,3,'Leading projects develops skills.','original'),
('127.57.d.3.B',2,'The chapter''s program of activities for advanced floral design might include:','["A holiday wreath sale", "Closing the chapter", "No events", "Cancelling"]'::jsonb,0,'Programs list planned activities.','original'),
('127.57.d.3.B',3,'A student who helps plan and run the holiday sale is:','["Breaking rules", "Participating in the local program of activities", "Quitting", "Avoiding service"]'::jsonb,1,'Participating supports the chapter.','original'),
('127.57.d.3.C',3,'An updated portfolio of event designs supports:','["Hiding skills", "Skipping classes", "Job applications and scholarships", "Losing credit"]'::jsonb,2,'Current portfolios show ability.','original'),
('127.57.d.3.C',2,'Documentation of floral experience should be:','["Discarded", "Never updated", "Hidden", "Updated regularly"]'::jsonb,3,'Keeping records current is a good habit.','original'),
('127.57.d.4.A',3,'The botanical term for the stalk that supports a flower is:','["Peduncle", "Petal", "Sepal", "Anther"]'::jsonb,0,'The peduncle connects flower to stem.','original'),
('127.57.d.4.A',4,'Advanced botanical terms help designers to:','["Avoid ordering", "Communicate precisely with growers and suppliers", "Confuse customers", "Replace design"]'::jsonb,1,'Precise language prevents ordering errors.','original'),
('127.57.d.4.B',3,'Red roses are traditionally associated with:','["Luck in business", "Patience", "Love and romance", "Mourning"]'::jsonb,2,'Red roses symbolize love.','original'),
('127.57.d.4.B',4,'White lilies are often used in sympathy designs because they symbolize:','["Surprise", "Wealth", "Anger", "Purity and peace"]'::jsonb,3,'Meaning guides flower selection.','original'),
('127.57.d.4.C',3,'A parallel design style is known for:','["Stems placed in clean, parallel lines", "No structure", "Round mass only", "Random placement"]'::jsonb,0,'Parallel design uses straight groups.','original'),
('127.57.d.4.C',4,'A contemporary design often emphasizes:','["Only tradition", "Abstract forms, negative space, and unusual materials", "Only symmetry", "Only roses"]'::jsonb,1,'Contemporary styles break conventions.','original'),
('127.57.d.4.D',3,'Sketching a design before building it helps to:','["Skip planning", "Waste time", "Test ideas and plan materials", "Avoid color"]'::jsonb,2,'Sketches clarify concepts.','original'),
('127.57.d.4.D',4,'A designer proposing a modern centerpiece might illustrate:','["Nothing", "A map", "A budget only", "Different arrangements in a contemporary style"]'::jsonb,3,'Illustrations help clients choose.','original'),
('127.57.d.4.E',3,'Layering in a basing technique means:','["Placing materials in overlapping tiers", "Randomly stacking", "Removing the base", "Using one flower"]'::jsonb,0,'Layering builds depth.','original'),
('127.57.d.4.E',4,'Terracing arranges materials:','["Without a base", "In steps at different levels", "In circles only", "All at one height"]'::jsonb,1,'Terraced bases create tiers.','original'),
('127.57.d.4.F',3,'A focal-emphasis technique such as grouping:','["Scatters flowers", "Removes the focal point", "Clusters similar items to draw the eye", "Avoids color"]'::jsonb,2,'Grouping builds emphasis.','original'),
('127.57.d.4.F',4,'Using a dramatic color or texture contrast at the center creates:','["Disunity", "Balance only", "No emphasis", "A strong focal point"]'::jsonb,3,'Contrast pulls attention.','original'),
('127.57.d.5.A',3,'When planning a fresh and permanent arrangement, the designer should:','["Choose materials suited to the purpose and lasting time", "Ignore the client", "Skip sketches", "Use anything"]'::jsonb,0,'Materials match function.','original'),
('127.57.d.5.A',4,'A combination of fresh and silk flowers is called:','["A corsage", "A mixed-media design", "A vase", "A boutonniere"]'::jsonb,1,'Mixed materials blend benefits.','original'),
('127.57.d.5.B',3,'A designer who builds a design with a layered base should:','["Add more layers always", "Remove color", "Evaluate whether the layers add depth without clutter", "Ignore results"]'::jsonb,2,'Evaluation improves work.','original'),
('127.57.d.5.B',4,'A weak basing design is one that:','["Has defined edges", "Is balanced", "Has clear layers", "Looks flat or cluttered and lacks structure"]'::jsonb,3,'Structure and clarity matter.','original'),
('127.57.d.5.C',3,'A well-executed focal-emphasis design:','["Leads the eye naturally to a main feature", "Has no variety", "Confuses the viewer", "Hides the focal point"]'::jsonb,0,'Focal emphasis guides the eye.','original'),
('127.57.d.5.C',4,'If a viewer''s eye wanders without resting, the design likely lacks:','["Water", "Clear emphasis", "Container", "Wire"]'::jsonb,1,'Emphasis anchors attention.','original'),
('127.57.d.6.A',3,'Good planning in floral design starts with:','["Skipping consultation", "Guessing", "Understanding the client''s needs and the event details", "Ordering random stems"]'::jsonb,2,'Planning begins with requirements.','original'),
('127.57.d.6.A',4,'Making a timeline for a large event helps ensure:','["Delays", "Waste", "Mistakes", "Designs are finished and delivered on time"]'::jsonb,3,'Timelines organize work.','original'),
('127.57.d.6.B',3,'An effective planning step is to:','["List needed materials, quantities, and tools", "Skip counting", "Order later", "Ignore inventory"]'::jsonb,0,'Lists prevent shortages.','original'),
('127.57.d.6.B',4,'Estimating how many stems are needed per centerpiece lets a designer:','["Overbuy", "Order the right amount and control cost", "Underbuy", "Skip budgeting"]'::jsonb,1,'Accurate counts save money.','original'),
('127.57.d.6.C',3,'A contingency plan for a large wedding order might include:','["Ignoring weather", "No extras", "Extra stems and backup suppliers", "Single supplier only"]'::jsonb,2,'Backups reduce risk.','original'),
('127.57.d.6.C',4,'Heat on delivery day is a factor to plan for because it can:','["Have no effect", "Improve them", "Raise water", "Shorten flower life and stress designs"]'::jsonb,3,'Temperature affects freshness.','original'),
('127.57.d.6.D',3,'A good consultation question is:','["What is the occasion, budget, and color preference?", "Do you like flowers?", "Who are you?", "Why are you here?"]'::jsonb,0,'Specific questions guide design.','original'),
('127.57.d.6.D',4,'Listening carefully to a client''s expectations helps a designer to:','["Charge more", "Create a design that meets their vision", "Delay the order", "Ignore wishes"]'::jsonb,1,'Understanding needs prevents mismatches.','original'),
('127.57.d.7.A',3,'A cascade bouquet is a term used for:','["Birthdays only", "Graduations only", "Weddings", "Funerals only"]'::jsonb,2,'Cascade bouquets are bridal.','original'),
('127.57.d.7.A',4,'A casket spray is a design term used for:','["Weddings", "Holidays", "Proms", "Funerals"]'::jsonb,3,'Sprays are sympathy pieces.','original'),
('127.57.d.7.B',3,'Applying balance and proportion to a wedding bouquet means:','["Sizing it to the bride and gown", "Ignoring the dress", "Making it huge always", "Using one flower"]'::jsonb,0,'Design fits the person.','original'),
('127.57.d.7.B',4,'For a funeral wreath, a designer applies the principles by:','["Making it tiny", "Creating a balanced, respectful, symmetrical form", "Ignoring tradition", "Using random colors"]'::jsonb,1,'Respectful design suits the occasion.','original'),
('127.57.d.7.C',3,'A current floral trend is use of:','["Only candy", "Only plastic", "Dried and preserved materials", "No flowers"]'::jsonb,2,'Preserved materials are popular.','original'),
('127.57.d.7.C',4,'Sustainable floral designs trend toward:','["More foam", "Imported only", "Less planning", "Foam-free mechanics and locally grown stems"]'::jsonb,3,'Eco-friendly options are growing.','original'),
('127.57.d.7.D',3,'Floral tools should be maintained by:','["Cleaning, sharpening, and storing them properly", "Sharing without cleaning", "Leaving them dirty", "Throwing them away"]'::jsonb,0,'Maintenance extends life.','original'),
('127.57.d.7.D',4,'Rust on shears can be prevented by:','["Leaving wet", "Drying and oiling the blades after use", "Soaking in water", "Storing outdoors"]'::jsonb,1,'Dry, oiled tools resist rust.','original'),
('127.57.d.7.E',3,'An occasion-specific design for a graduation might use:','["No flowers", "Black only", "The school colors", "Random colors"]'::jsonb,2,'Colors reflect the event.','original'),
('127.57.d.7.E',4,'Designing for a memorial service differs from a celebration in that it uses:','["Party hats", "Neon colors", "Balloons", "Subdued tones and respectful forms"]'::jsonb,3,'Tone matches occasion.','original'),
('127.57.d.8.A',3,'During a consultation, a designer gathers details such as:','["Occasion, venue, budget, and color palette", "Favorite TV", "Shoe size", "Phone brand"]'::jsonb,0,'These details shape the proposal.','original'),
('127.57.d.8.A',4,'Visiting the event venue before designing helps to:','["Skip planning", "See the space, lighting, and logistics", "Delay the order", "Reduce quality"]'::jsonb,1,'Venue details affect design.','original'),
('127.57.d.8.B',3,'A designer selects arrangements that:','["Use the rarest flowers", "Ignore the budget", "Meet the client''s objectives and budget", "Cost the most"]'::jsonb,2,'Selection balances goals and costs.','original'),
('127.57.d.8.B',4,'If the client''s budget is tight, a designer can:','["Refuse the job", "Ignore the budget", "Use only wilted stems", "Use seasonal blooms and fewer focal flowers"]'::jsonb,3,'Creative choices fit budgets.','original'),
('127.57.d.8.C',3,'A floral proposal typically includes:','["Design concepts, pricing, and timeline", "A joke", "Nothing", "Only a logo"]'::jsonb,0,'Proposals set expectations.','original'),
('127.57.d.8.C',4,'Showing photos or mock-ups in a proposal helps clients to:','["Get confused", "Visualize the finished designs", "Delay approval", "Skip decisions"]'::jsonb,1,'Visuals clarify ideas.','original'),
('127.57.d.8.D',3,'A production schedule works backward from the:','["Menu", "Clock time", "Event date", "Order date"]'::jsonb,2,'Backward planning ensures readiness.','original'),
('127.57.d.8.D',4,'Allowing extra time to condition flowers in the schedule helps ensure:','["Higher cost", "Late delivery", "Wilting", "Blooms open properly and last"]'::jsonb,3,'Hydration time improves quality.','original'),
('127.57.d.8.E',3,'A procurement plan identifies:','["What to buy, from whom, and when", "Only prices", "Only brands", "Only colors"]'::jsonb,0,'Procurement ensures supplies arrive.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
